package cli

import (
	"strings"
	"testing"

	"github.com/chemaclass/agnostic-ai/internal/adapters/header"
)

// legacyDefaultBody is the AGNOSTIC_AI.md body sync seeded before the
// short editable template.
const legacyDefaultBody = "" +
	"# AI Project Conventions\n" +
	"\n" +
	"This file is regenerated by [agnostic-ai](https://github.com/chemaclass/agnostic-ai). Every supported AI tool reads a copy of this body from its native entry-point (CLAUDE.md, AGENTS.md, GEMINI.md, CONVENTIONS.md, ...) so a single source of truth drives every target.\n" +
	"\n" +
	"## Where the specs live\n" +
	"\n" +
	"- **Agents**: `.agnostic-ai/agents/`\n" +
	"- **Skills**: `.agnostic-ai/skills/`\n" +
	"- **Rules**: `.agnostic-ai/rules/` (one file per rule)\n" +
	"- **Hooks**: `.agnostic-ai/hooks/` (rendered into the target-native location)\n" +
	"- **MCP servers**: `.agnostic-ai/mcps/`\n" +
	"- **Commands**: `.agnostic-ai/commands/`\n" +
	"- **Settings**: `.agnostic-ai/settings/` (portable model and permission defaults where targets support them)\n" +
	"- **Reviews**: `.agnostic-ai/reviews/` (code-review bot guidance; Cursor BUGBOT.md today)\n" +
	"- **Environments**: `.agnostic-ai/environments/` (dev-env bootstrap; Cursor environment.json today)\n" +
	"- **Ignore**: `.agnostic-ai/ignore/` (agent ignore patterns; .cursorignore, .geminiignore, .aiderignore)\n" +
	"\n" +
	"## Target-specific overlays\n" +
	"\n" +
	"Per-target configuration that does not fit the agnostic spec kinds above lives under `.agnostic-ai/overlays/`. The Claude adapter, for example, captures the non-`hooks` portion of `.claude/settings.json` (statusLine, enabledPlugins, ...) into `.agnostic-ai/overlays/claude.settings.json` on `import claude`. `sync` reads that overlay and layers the spec-derived `hooks` key on top.\n" +
	"\n" +
	"## Workflow\n" +
	"\n" +
	"- Author specs under the directories above.\n" +
	"- Run `agnostic-ai sync` to regenerate per-target output files.\n" +
	"- Edit only the source specs; the per-target files (including this one) are overwritten on each sync.\n"

func TestDoctor_HintsWhenAgnosticEntryPointHoldsOldDefault(t *testing.T) {
	setupDoctorLintProject(t, map[string]string{
		"AGNOSTIC_AI.md": header.With(legacyDefaultBody, header.FormatMarkdown),
	})

	out, err := runDoctor(t)

	if err != nil {
		t.Fatalf("the hint must not fail doctor: %v\n%s", err, out)
	}
	if !strings.Contains(out, "Instructions:\n  i .agnostic-ai/AGNOSTIC_AI.md still holds the old default text") {
		t.Errorf("doctor should hint that the old default text can be trimmed:\n%s", out)
	}
}

func TestDoctor_HintsWhenImportedOldDefaultLostItsHeader(t *testing.T) {
	setupDoctorLintProject(t, map[string]string{
		"AGNOSTIC_AI.md": legacyDefaultBody + "\n## Project\n\nOwn text.\n",
	})

	out, _ := runDoctor(t)

	if !strings.Contains(out, "still holds the old default text") {
		t.Errorf("doctor should hint for the old default text without its header:\n%s", out)
	}
}

func TestDoctor_NoHintForSeededTemplate(t *testing.T) {
	setupDoctorLintProject(t, nil)

	out, err := runDoctor(t)

	if err != nil {
		t.Fatalf("doctor failed: %v\n%s", err, out)
	}
	if strings.Contains(out, "old default text") {
		t.Errorf("the seeded template needs no hint:\n%s", out)
	}
}
